// Evento SESSION_NEW do WTS/Helena. Dados reais em body.content.
const b = $input.first().json.body || $input.first().json;
const c = b.content || b;

const companyId = c.companyId || null;
const sessionId = c.id || null;
const contactId = c.contactId || (c.contactDetails ? c.contactDetails.id : null);
const contactDetails = c.contactDetails || {};
const contactName = (contactDetails.name && contactDetails.name.trim()) ? contactDetails.name.trim() : 'Sem nome';
const telefoneFormatado = contactDetails.phonenumberFormatted || contactDetails.phonenumber || '';
const telefoneLimpo = (contactDetails.phonenumber || contactDetails.phonenumberFormatted || '').toString().replace(/\D/g, '');

const channelDetails = c.channelDetails || {};
const numeroRecebido = (channelDetails.id || '').toString().replace(/\D/g, '');

// ---------------------------------------------------------------------
// Mapeamento número do WhatsApp (número de leads) -> unidade.
// Aceita o número com e sem o prefixo de país 55, pois ainda não
// confirmamos em qual formato o channelDetails.id chega para esta conta.
// Penha:   21 9 9195-0355 | Caxias: 21 98799-1162 | Recreio: 21 98746-9219
// ---------------------------------------------------------------------
const NUMERO_PARA_UNIDADE = {
    '21991950355': 'penha',
    '5521991950355': 'penha',
    '21987991162': 'caxias',
    '5521987991162': 'caxias',
    '21987469219': 'recreio',
    '5521987469219': 'recreio'
};
const unidadeDetectada = NUMERO_PARA_UNIDADE[numeroRecebido] || 'nao_definida';

// Tags de unidade já cadastradas no Helena (aplicar quando o mapeamento acima estiver pronto)
// IDs das tags do PAINEL (nao das tags de contato) -- sao pools diferentes no Helena/WTS.
// Tag de contato "Unidade Penha/Recreio/Caxias" NAO funciona aqui; o card exige a tag do painel.
const TAG_UNIDADE = {
    penha: 'ae3a727e-c0e9-44be-be97-97f8bb1735de',
    recreio: '9adfe4f5-c03b-497d-bc69-a207e3be5305',
    caxias: '0cf0b4b3-567e-4fcc-8577-d70916a73ca5'
};
const tagUnidadeId = TAG_UNIDADE[unidadeDetectada] || null;

// ---------------------------------------------------------------------
// Detecção de origem (Facebook / Instagram / Orgânico) via UTM do anúncio,
// com fallback para a plataforma do canal quando não há UTM.
// ---------------------------------------------------------------------
const utm = c.utm || null;
const utmSource = (utm && utm.source) ? String(utm.source).toUpperCase() : null;
const campanhaNome = (utm && (utm.headline || utm.campaign || utm.campaignName)) || null;
const platform = (channelDetails.platform || c.channelType || '').toString().toUpperCase();

const origemRaw = utmSource || platform || 'DESCONHECIDO';
let origemDetectada;
if (origemRaw.includes('INSTAGRAM')) origemDetectada = 'instagram';
else if (origemRaw.includes('FACEBOOK') || origemRaw.includes('META')) origemDetectada = 'facebook';
else origemDetectada = 'organico';

// Tags de origem do PAINEL (mesmo pool das tags de unidade, distinto das tags de contato)
const TAG_ORIGEM = {
    facebook: '0b6a4e15-d813-4298-b6a2-80689ff01551',
    instagram: 'ad5ddba4-e1f8-4ec4-9ef0-594b72723309',
    organico: '311daa9c-2366-4156-a4b4-856237133ea0'
};
const tagOrigemId = TAG_ORIGEM[origemDetectada] || null;

const tagIdsCard = [tagUnidadeId, tagOrigemId].filter(Boolean);

// Nome de exibição da unidade, para o campo personalizado "Unidade" do painel
const UNIDADE_DISPLAY = { penha: 'Penha', recreio: 'Recreio', caxias: 'Caxias' };
const unidadeDisplay = UNIDADE_DISPLAY[unidadeDetectada] || null;

const customFieldsCard = {};
if (unidadeDisplay) customFieldsCard.unidade = unidadeDisplay;
if (campanhaNome) customFieldsCard['campanha-'] = campanhaNome;

// Config do Kanban (declarada direto no código — sem Supabase, clínica única)
const KANBAN = {
    helena_token: 'pn_FeGSOXOMB8wT3X4VfS4QoxrxwMBxWgKsSZKJgH8qkPs',
    panel_id: '8d009d78-8d18-4a74-8d56-1956e2f5e26a',
    step_leads_id: '20e5cc71-4548-4f11-89f4-759cbfdc263d'
};

const agora = DateTime.now().setZone('America/Sao_Paulo');
const dataEntrada = agora.toFormat('dd/MM/yyyy');
const horaEntrada = agora.toFormat('HH:mm');

const descricaoPartes = [
    `Entrada: ${dataEntrada} às ${horaEntrada}`,
    `Telefone: ${telefoneFormatado}`,
    `Unidade (WhatsApp recebido): ${unidadeDetectada}`,
    `Origem: ${origemDetectada}`
];
if (campanhaNome) descricaoPartes.push(`Campanha: ${campanhaNome}`);
const descricao = descricaoPartes.join('\n');

return {
    json: {
        companyId,
        sessionId,
        contactId,
        contactName,
        telefoneFormatado,
        telefoneLimpo,
        numeroRecebido,
        unidadeDetectada,
        tagUnidadeId,
        origemDetectada,
        tagOrigemId,
        campanhaNome,
        tagIdsCard,
        customFieldsCard,
        kanban: KANBAN,
        dataEntrada,
        horaEntrada,
        descricao
    }
};

const resp = $input.first().json;
const items = Array.isArray(resp) ? resp : (resp.items ?? []);
const hasCard = Array.isArray(items) && items.length > 0;
const cardId = hasCard ? (items[0].id ?? null) : null;
return [{ json: { hasCard, cardId } }];

